import csv
import difflib
import re
from collections import Counter, defaultdict
from pathlib import Path

BASE = Path(r"c:\Users\proch\OneDrive\Pulpit\repozytorium\lab2\data")


def load_csv(path: Path):
    rows = []
    malformed = 0
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f, restkey="__EXTRA__", restval="__MISSING__")
        fieldnames = reader.fieldnames
        for r in reader:
            if "__EXTRA__" in r or "__MISSING__" in r.values():
                malformed += 1
            rows.append(r)
    return fieldnames, rows, malformed


def split_subject_body(text: str):
    lines = text.splitlines()
    if lines and lines[0].startswith("Subject:"):
        subj = lines[0][len("Subject:"):].strip()
        body = "\n".join(lines[1:]).strip()
    else:
        subj = ""
        body = text.strip()
    return subj, body


def norm_text(s: str):
    return re.sub(r"\s+", " ", s.lower()).strip()


def norm_subject(s: str):
    s = s.strip()
    while True:
        new_s = re.sub(r"^(re|fw|fwd)\s*:\s*", "", s, flags=re.I).strip()
        if new_s == s:
            break
        s = new_s
    return re.sub(r"\s+", " ", s.lower()).strip()


def word_set(s: str):
    return set(re.findall(r"[a-z0-9]{3,}", s.lower()))


def jaccard(a: set, b: set):
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)


def check_formatting(name: str, rows):
    stats = Counter()
    examples = defaultdict(list)
    for r in rows:
        t = r["text"]
        mid = r["message_id"]
        lbl = r["label"]
        subj, body = split_subject_body(t)

        if not subj:
            stats["empty_subject"] += 1
            examples["empty_subject"].append((mid, lbl))
        if not body:
            stats["empty_body"] += 1
            examples["empty_body"].append((mid, lbl))
        if "\ufffd" in t:
            stats["unicode_replacement_char"] += 1
            examples["unicode_replacement_char"].append((mid, lbl))
        if re.search(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", t):
            stats["control_chars"] += 1
            examples["control_chars"].append((mid, lbl))
        if any(ord(ch) > 127 for ch in t):
            stats["non_ascii"] += 1
        if "\r\n" in t:
            stats["crlf_newlines"] += 1
        if re.search(r"&(?:#\d+|#x[0-9a-f]+|[a-z]+);", t, re.I):
            stats["html_entities"] += 1
            if len(examples["html_entities"]) < 3:
                examples["html_entities"].append((mid, lbl, re.findall(r"&(?:#\d+|#x[0-9a-f]+|[a-z]+);", t, re.I)[:4]))
        if re.search(r"<(html|body|table|tr|td|div|p|br|a\s|font|img|head|meta|style|script)\b", t, re.I):
            stats["html_tags"] += 1
            examples["html_tags"].append((mid, lbl))
        if re.search(r"=(?:20|3D|09|A0|E2|C2|C3)\b|=\r?\n", t):
            stats["quoted_printable_artifacts"] += 1
            if len(examples["quoted_printable_artifacts"]) < 3:
                examples["quoted_printable_artifacts"].append((mid, lbl))
        if re.search(r"^[A-Za-z0-9+/]{60,}={0,2}$", t, re.M):
            stats["base64_like_lines"] += 1
            examples["base64_like_lines"].append((mid, lbl))
        if re.search(r"^>", body, re.M):
            stats["quoted_reply_lines"] += 1
        if re.search(r"^URL:\s*http", body, re.M) and re.search(r"^Date:\s*", body, re.M):
            stats["rss_url_date_format"] += 1
            stats[f"rss_url_date_format_{lbl}"] += 1
        if re.search(r"spamassassin\.taint\.org|jm@|yyyy@", t, re.I):
            stats["corpus_trap_or_anon_addr"] += 1
            stats[f"corpus_trap_{lbl}"] += 1
        if re.search(r"([#=*~_-])\1{6,}", t):
            stats["ascii_dividers_or_banners"] += 1
        if re.search(r"https?://|www\.", t, re.I):
            stats["contains_url"] += 1
        if re.search(r"[\w.+-]+@[\w-]+\.[\w.-]+", t):
            stats["contains_email_addr"] += 1
        if re.search(r"\[[^\]]{2,30}\]", subj):
            stats["subject_bracket_tag"] += 1
            stats[f"subject_bracket_tag_{lbl}"] += 1
        if re.search(r"^(re|fw|fwd)\s*:", subj, re.I):
            stats["reply_or_fwd_subject"] += 1
            stats[f"reply_or_fwd_{lbl}"] += 1
        if re.search(r"unsubscribe|mailing list|list-unsubscribe|sourceforge\.net/lists|rpm-list|exmh-users|razor-users|spambayes|ilug", t, re.I):
            stats["mailing_list_or_unsub_footer"] += 1
            stats[f"ml_footer_{lbl}"] += 1
        # Check uppercase ratio in subject/body
        letters = [c for c in t if c.isalpha()]
        if letters and (sum(1 for c in letters if c.isupper()) / len(letters)) > 0.4:
            stats["high_uppercase_ratio_gt_40pct"] += 1
            examples["high_uppercase_ratio_gt_40pct"].append((mid, lbl))

    print(f"\n--- Formatting stats for {name} (n={len(rows)}) ---")
    for k in sorted(stats.keys()):
        print(f"  {k}: {stats[k]}")
    for k, v in examples.items():
        print(f"  examples[{k}]: {v[:5]}")


def main():
    train_cols, train_rows, train_mal = load_csv(BASE / "train.csv")
    val_cols, val_rows, val_mal = load_csv(BASE / "validation.csv")

    print("=== 1-4 & 6. BASIC INTEGRITY ===")
    for name, cols, rows, mal in [
        ("train.csv", train_cols, train_rows, train_mal),
        ("validation.csv", val_cols, val_rows, val_mal),
    ]:
        labels = Counter(r["label"] for r in rows)
        ids = [r["message_id"] for r in rows]
        empty_id = sum(1 for r in rows if not r["message_id"] or not r["message_id"].strip())
        empty_text = sum(1 for r in rows if not r["text"] or not r["text"].strip())
        empty_label = sum(1 for r in rows if not r["label"] or not r["label"].strip())
        print(
            f"{name}: cols={cols}, rows={len(rows)}, malformed={mal}, labels={dict(labels)}, "
            f"unique_ids={len(set(ids))}/{len(ids)}, empty=(id:{empty_id}, text:{empty_text}, label:{empty_label})"
        )

    train_ids = {r["message_id"] for r in train_rows}
    val_ids = {r["message_id"] for r in val_rows}
    print(f"Cross-split message_id overlap: {len(train_ids & val_ids)}")

    # 5. Duplicate & near-duplicate content checks
    print("\n=== 5. DUPLICATE & NEAR-DUPLICATE CONTENT ===")
    all_rows = [("train", r) for r in train_rows] + [("val", r) for r in val_rows]

    def count_dups(items):
        c = Counter(items)
        return {k: v for k, v in c.items() if v > 1}

    for label_scope, subset in [("train", train_rows), ("val", val_rows), ("combined", train_rows + val_rows)]:
        exact_text_dups = count_dups([r["text"] for r in subset])
        norm_text_dups = count_dups([norm_text(r["text"]) for r in subset])
        exact_body_dups = count_dups([split_subject_body(r["text"])[1] for r in subset])
        norm_body_dups = count_dups([norm_text(split_subject_body(r["text"])[1]) for r in subset])
        print(
            f"[{label_scope}] exact_text_dups={len(exact_text_dups)}, norm_text_dups={len(norm_text_dups)}, "
            f"exact_body_dups={len(exact_body_dups)}, norm_body_dups={len(norm_body_dups)}"
        )

    # List exact/norm body duplicates if any
    body_groups = defaultdict(list)
    for sp, r in all_rows:
        nb = norm_text(split_subject_body(r["text"])[1])
        body_groups[nb].append((sp, r["message_id"], r["label"], split_subject_body(r["text"])[0]))
    for nb, grp in body_groups.items():
        if len(grp) > 1:
            print(f"  Norm-body duplicate group (n={len(grp)}): {grp}")

    # Near-duplicates by Jaccard on body words >= 0.65 (and SequenceMatcher check)
    prepped = []
    for sp, r in all_rows:
        subj, body = split_subject_body(r["text"])
        prepped.append((sp, r["message_id"], r["label"], subj, norm_subject(subj), body, word_set(body)))

    near_within_train = []
    near_within_val = []
    near_cross = []
    for i in range(len(prepped)):
        for j in range(i + 1, len(prepped)):
            sp1, id1, lbl1, s1, ns1, b1, ws1 = prepped[i]
            sp2, id2, lbl2, s2, ns2, b2, ws2 = prepped[j]
            jac = jaccard(ws1, ws2)
            if jac >= 0.55:
                seq = difflib.SequenceMatcher(None, norm_text(b1)[:1500], norm_text(b2)[:1500]).ratio()
                if jac >= 0.65 or seq >= 0.70:
                    entry = (round(jac, 2), round(seq, 2), f"{sp1}:{id1}({lbl1})", f"{sp2}:{id2}({lbl2})", s1[:45], s2[:45])
                    if sp1 == sp2 == "train":
                        near_within_train.append(entry)
                    elif sp1 == sp2 == "val":
                        near_within_val.append(entry)
                    else:
                        near_cross.append(entry)

    print(f"Near-duplicate body pairs -> within train: {len(near_within_train)}, within val: {len(near_within_val)}, cross train-val: {len(near_cross)}")
    for cat, lst in [("within_train", near_within_train), ("within_val", near_within_val), ("cross_train_val", near_cross)]:
        for item in lst[:10]:
            print(f"  [{cat}] {item}")

    # Shared normalized subjects (potential same email thread!)
    subj_groups = defaultdict(list)
    for sp, mid, lbl, subj, nsubj, _, _ in prepped:
        if nsubj:
            subj_groups[nsubj].append((sp, mid, lbl, subj))

    shared_subj_train = 0
    shared_subj_val = 0
    shared_subj_cross = []
    for nsubj, grp in subj_groups.items():
        if len(grp) > 1:
            splits = {g[0] for g in grp}
            if splits == {"train"}:
                shared_subj_train += 1
            elif splits == {"val"}:
                shared_subj_val += 1
            else:
                shared_subj_cross.append((nsubj, grp))

    print(f"\nShared normalized subjects (threads) -> only train: {shared_subj_train}, only val: {shared_subj_val}, cross train-val: {len(shared_subj_cross)}")
    for nsubj, grp in shared_subj_cross:
        print(f"  [cross-thread] '{nsubj}': {[(g[0], g[1], g[2]) for g in grp]}")

    # 7. Formatting checks
    check_formatting("train.csv", train_rows)
    check_formatting("validation.csv", val_rows)

    # Check top bracket tags by split & label
    print("\n--- Mailing list bracket tags in Subject ---")
    for name, rows in [("train", train_rows), ("val", val_rows)]:
        c = Counter()
        for r in rows:
            subj, _ = split_subject_body(r["text"])
            for tag in re.findall(r"\[[^\]]{2,30}\]", subj):
                c[(tag, r["label"])] += 1
        print(f"  {name}: {c.most_common(15)}")


if __name__ == "__main__":
    main()
